import React, { useState } from "react";
import { Card, Button, Form, Placeholder } from "react-bootstrap";
import { useFetcher } from "react-router-dom";
import useSWR from "swr";
import PlaceholderStatistic from "./PlaceholderStatistic";

const Plex = () => {
  const token = "6tySK2p9ZxyKAySWyyNU";
  const privateIp = "http://192.168.0.220:32400/";
  const statisticsQuery = privateIp + "/statistics/media";
  const fetcher = new useFetcher();
  const { data, error, isLoading } = useSWR(statisticsQuery, fetcher);

  if (error) return <div>failed to load</div>;
  if (isLoading) return <PlaceholderStatistic />;
  console.log(data);
  return (
    <>
      <Form></Form>
    </>
  );
};

export default Plex;
